import pathlib,re,subprocess

def _run(args):
    result=subprocess.run(args,capture_output=True,text=True,timeout=10)
    if result.returncode:raise ValueError((result.stderr or result.stdout).strip())
    return result.stdout

def make_node_csr(private_key,node_name,csr_path):
    if not re.fullmatch(r"[a-z0-9][a-z0-9.-]{0,62}",node_name):raise ValueError("invalid node name")
    subject="/CN=system:node:"+node_name+"/O=system:nodes"
    _run(["openssl","req","-new","-key",str(private_key),"-subj",subject,"-out",str(csr_path)])
    return pathlib.Path(csr_path)

def validate_node_certificate(certificate,ca_file,node_name,at_time):
    expected="CN=system:node:"+node_name
    subject=_run(["openssl","x509","-in",str(certificate),"-noout","-subject","-nameopt","RFC2253"]).strip()
    if expected not in subject or "O=system:nodes" not in subject:raise ValueError("node certificate identity mismatch: "+subject)
    _run(["openssl","verify","-attime",str(int(at_time)),"-CAfile",str(ca_file),str(certificate)])
    return {"subject":subject,"valid_at":int(at_time)}
